#include "dns_core.h"
static uint16_t d16(const uint8_t*p){return(uint16_t)(((uint16_t)p[0]<<8)|p[1]);}
static int name_end(const uint8_t*m,uint32_t n,uint32_t start,uint32_t*consumed){uint32_t pos=start,used=0,total=0;uint32_t seen[32];uint8_t jumps=0;for(;;){if(pos>=n)return -1;uint8_t len=m[pos];if((len&0xc0U)==0xc0U){if(pos+1>=n)return -1;uint32_t target=((uint32_t)(len&0x3fU)<<8)|m[pos+1];if(target>=n||jumps==32)return -1;for(uint8_t i=0;i<jumps;i++)if(seen[i]==target)return -1;seen[jumps++]=target;if(!used)used=pos+2-start;pos=target;continue;}if(len&0xc0U)return -1;pos++;if(len==0){if(!used)used=pos-start;break;}if(len>63||pos+len>n)return -1;total+=(uint32_t)len+1;if(total>254)return -1;pos+=len;}*consumed=used;return 0;}
int dns_validate_message(const uint8_t*m,uint32_t n,struct dns_summary*out){if(!m||!out||n<12||n>DNS_PACKET_MAX)return -1;uint16_t q=d16(m+4),a=d16(m+6),ns=d16(m+8),ar=d16(m+10);if((uint32_t)q+a+ns+ar>DNS_RECORD_MAX)return -1;uint32_t pos=12,used;for(uint32_t i=0;i<q;i++){if(name_end(m,n,pos,&used)!=0||used>n-pos)return -1;pos+=used;if(n-pos<4)return -1;pos+=4;}uint32_t records=(uint32_t)a+ns+ar;for(uint32_t i=0;i<records;i++){if(name_end(m,n,pos,&used)!=0||used>n-pos)return -1;pos+=used;if(n-pos<10)return -1;uint16_t rdlen=d16(m+pos+8);pos+=10;if(rdlen>n-pos)return -1;pos+=rdlen;}if(pos!=n)return -1;out->id=d16(m);out->questions=q;out->answers=a;out->authorities=ns;out->additional=ar;out->response=(uint8_t)((m[2]>>7)&1U);out->rcode=(uint8_t)(m[3]&15U);return 0;}
